 Ext._define('auditoria.auditlog.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'auditoria.auditlog.Window',

    configOrderToolBar: [
        "search",
        "contentTypeFilter",
        "->",
    ],


    getFilterMenu: function() {
        if(!this._filterMenu)
            this._filterMenu = [
                {
                    text: 'Período do evento',
                    scope: this,
                    handler: this.filterData
                }
            ];

        return this._filterMenu;
    },

    'filterData': function() {
        var wnd = Ext._create('Ext.Window', {
            'title': 'Filtro por data',
            'width': 320,
            'modal': true,
            'border': false,
            'items': [
                Ext._create('Ext.form.FormPanel', {
                    'border': false,
                    'frame': true,
                    'items': [
                        {
                            'fieldLabel': 'De',
                            'name': 'de',
                            'xtype': 'tk-datetimefield',
                            'allowBlank': true
                        },
                        {
                            'fieldLabel': 'Até',
                            'name': 'ate',
                            'xtype': 'tk-datetimefield',
                            'allowBlank': true
                        }
                    ]
                })
            ],
            'buttons': [
                {
                    'text': 'Selecionar',
                    'scope': this,
                    'handler': function() {
                        var form = wnd.getComponent(0).getForm();
                        var data = {
                            'de': Ext.util.Format.date(form.findField('de').getValue(), 'Y-m-d H:i'),
                            'ate': Ext.util.Format.date(form.findField('ate').getValue(), 'Y-m-d H:i')
                        };

                        if(data.de !== '')
                            this.setFilterProperty('timestamp__gte', data.de, 1006, false);
                        else
                            this.removeFilterProperty('timestamp__gte', 1006, false);

                        if(data.ate !== '')
                            this.setFilterProperty('timestamp__lte', data.ate, 1007, false);
                        else
                            this.removeFilterProperty('timestamp__lte', 1007, false);

                        this.getStore().load({});
                        wnd.destroy();
                    }
                },
                {
                    'text': 'Fechar',
                    'handler': function() { wnd.destroy(); }
                }
            ]
        }).show();
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Id', dataIndex: 'desc', id: 'autoExpandColumn',hidden:true},
                    {header: 'Chave', dataIndex: 'id', width: 90, hidden:true},
                    {header: 'Id', dataIndex: 'object_id', width: 90},
                    {header: 'Modelo', dataIndex: 'model', width: 250},
                    {header: 'Modelo', dataIndex: 'content_type', width: 250,hidden:true},
                    {header: 'Ação', dataIndex: 'action', width: 250},
                    {header: 'Usuário', dataIndex: 'user', width: 250},
                    {header: 'Quando', dataIndex: 'timestamp', width: 250, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i:s')},
                    {header: 'Endereço IP', dataIndex: 'remote_addr', width: 250},

                    //{header: 'De onde', dataIndex: 'host_address', width: 130}
                ]
            );

        return this._columnModel;
    },

    getContentTypeFilterAction: function () {
        if (!this._contentTypeFilter)
            this._contentTypeFilter = Ext._create("auditoria.auditlog.ContentTypeFilterAction", { objToFilter: this });
        return this._contentTypeFilter;
    },
});

core.RestfulGrid.register(
    'auditoria.auditlog.Restful',
    'auditoria.auditlog.Grid'
);